{% from "hipersign_trading/templates/print/macros.html" import styles, header, items, totals, signs, bank %}
{{ styles() }}
<div class="hs-doc">
{{ header("QUOTATION", "عرض سعر", doc.name, doc.transaction_date, doc.company) }}
<div class="hs-two"><div><div class="hs-h4">Prepared for · مقدم إلى</div><b>{{ doc.customer_name or doc.party_name }}</b><br>{{ doc.address_display or "" }}{% if doc.contact_display %}<br>Attn: {{ doc.contact_display }}{% if doc.contact_mobile %} · {{ doc.contact_mobile }}{% endif %}{% endif %}{% if doc.tax_id %}<br>TRN {{ doc.tax_id }}{% endif %}</div><div><div class="hs-h4">Details · التفاصيل</div>{% if doc.hs_subject %}Subject: {{ doc.hs_subject }}<br>{% endif %}Valid until: {{ frappe.utils.formatdate(doc.valid_till) }}<br>Payment terms: {{ doc.payment_terms_template or "As agreed" }}<br>Prepared by: {{ frappe.db.get_value("User", doc.owner, "full_name") }}</div></div>
{{ items(doc) }}
{{ totals(doc) }}
<div class="hs-h4" style="margin-top:14px">Terms & conditions · الشروط والأحكام</div><div class="hs-note">{{ doc.terms or "" }}</div>
{{ signs("For " ~ doc.company, "Accepted by the customer — name, signature & stamp") }}
</div>
